class TrainingDummy:
    def __init__(self, name):
        self.name = name
        self.hit_count = 0

    def record_hit(self):
        self.hit_count += 1
        print(f"{self.name} has been hit {self.hit_count} time(s).")


dummy = TrainingDummy("Practice Dummy")
dummy.hit_count = 5
dummy.record_hit()
